'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

function all(chunks, opts) {
  const p = createParser(opts);
  const out = [];
  for (const c of chunks) out.push(...p.push(c));
  return out.concat(p.end());
}
function everySplit(text, expected, opts) {
  assert.deepEqual(parse(text, opts), expected, JSON.stringify(text));
  for (let i = 0; i <= text.length; i++)
    for (let j = i; j <= text.length; j++)
      assert.deepEqual(all([text.slice(0, i), '', text.slice(i, j), text.slice(j)], opts), expected, `${JSON.stringify(text)} @${i},${j}`);
}
function errLine(text, n) {
  for (let i = 0; i <= text.length; i++) {
    assert.throws(() => all([text.slice(0, i), text.slice(i)]), e => e instanceof SyntaxError && e.message.includes(`line ${n}`), `${JSON.stringify(text)} @${i}`);
  }
}

everySplit('', []);
everySplit('\uFEFF', []);
everySplit('\n', [['']]);
everySplit('\n\n', [[''], ['']]);
everySplit('a\n', [['a']]);
everySplit('a\r\nb\rc\n', [['a'], ['b'], ['c']]);
everySplit('a\r\r\nb', [['a'], [''], ['b']]);
everySplit('\uFEFFa,\uFEFFb', [['a', '\uFEFFb']]);
everySplit('"a""b",c\r\n"x\r\ny\rz",', [['a"b', 'c'], ['x\r\ny\rz', '']]);
everySplit('a"b,c""', [['a"b', 'c""']]);
everySplit('""', [['']]);
everySplit('"",""\r', [['', '']]);
everySplit('a;b,c\n', [['a', 'b,c']], { delimiter: ';' });
everySplit('a\tb', [['a', 'b']], { delimiter: '\t' });
everySplit('\ud83d\ude00,x', [['\ud83d\ude00', 'x']]);

errLine('"a" ,b', 1);
errLine('x\r\n"a\r\nb"x', 3);
errLine('x\r"a\nb\r"y', 4);
errLine('a\n"open\r\n', 3);
errLine('"', 1);

// emit immediately
const p = createParser();
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), e => e.constructor === Error);
assert.throws(() => createParser().push(1), TypeError);
